/**
 * Dumps produced once by `luajit -b` (LuaJIT 2.1.1772148810, FFI and FR2 flags) from small
 * self-owned sources. Embedded as hex so no binary is committed; they are producer
 * goldens, not an automated real-toolchain lane.
 */
export const LUAJIT_GOLDENS = {
  /** `local up = 7; local function f(a, b) return a + b + up + 1.5 end` plus table, string, 64-bit constants; stripped. */
  stripped:
    "1b4c4a020e2300020401000105200201002d03000020020302160200024c02020000c0018080e0ff03680700080004010d2900070033010000350201001203010029050100290602004203030227040200120502002a06000028070300320000804a03060003b5b8f0fe0d020a68656c6c6f010302000301030204008080b080040206780768690081ffffff1fffffff960400",
  /** The same source with `-g` debug information and chunk name `@a.lua`. */
  debug:
    "",
  /** Nested functions, numeric and generic `for` loops, complex/int64 constants, negative table values; `-g`. */
  loops:
    "",
  /** A 130-byte string (two-byte tag), a lone 0xff string (invalid UTF-8) and 300+ lines (two-byte line info); `-g`. */
  wide: "",
} as const;

export const luajitGolden = (name: keyof typeof LUAJIT_GOLDENS): Buffer =>
  Buffer.from(LUAJIT_GOLDENS[name], "hex");

const uleb = (value: number): number[] => {
  const bytes: number[] = [];
  let rest = value;
  do {
    const low = rest % 128;
    rest = Math.floor(rest / 128);
    bytes.push(rest > 0 ? low | 0x80 : low);
  } while (rest > 0);
  return bytes;
};

/** Stripped dump whose single constant table holds `nilCount` one-byte nil entries. */
export const luajitNilTableDump = (nilCount: number): Buffer => {
  const body = Buffer.concat([
    // flags, parameters, frame size, upvalues; one GC constant, no numbers, no instructions
    Buffer.from([0, 0, 1, 0, 1, 0, 0]),
    // table tag, array count, hash count, then the nil entries
    Buffer.from([1, ...uleb(nilCount), 0]),
    Buffer.alloc(nilCount),
  ]);
  return Buffer.concat([
    Buffer.from([0x1b, 0x4c, 0x4a, 2, 0x02, ...uleb(body.length)]),
    body,
    Buffer.alloc(1),
  ]);
};
